from collections import deque

def bfs_path_search(graph, start, goal):
    if start == goal:
        return [start]  # If start node is the goal, return the start node itself as the path.

    visited = set()  # Track visited nodes to avoid cycles.
    queue = deque([(start, [start])])  # Queue of tuples (node, path).

    while queue:
        current_node, path = queue.popleft()
        visited.add(current_node)

        for neighbor in graph[current_node]:
            if neighbor not in visited:
                if neighbor == goal:
                    return path + [neighbor]  # Return the path if the goal is reached.
                else:
                    queue.append((neighbor, path + [neighbor]))

    return None  # If the goal node is not reachable.

# Example usage:
