```python
from collections import deque

def is_valid(x, y, grid):
    """Check if the coordinates (x, y) are within the grid and not an obstacle."""
    return 0 <= x < len(grid) and 0 <= y < len(grid[0]) and grid[x][y] == 0

def bfs(grid, start, end):
    """Perform BFS to find a path from start to end in the grid."""
    if start == end:
        return [start]

    queue = deque([start])
    visited = set([start])
    path = {}
    path[start] = None

    while queue:
        x, y = queue.popleft()

        if (x, y) == end:
            break

        # Explore neighbors
        for dx, dy in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            nx, ny = x + dx, y + dy
            if is_valid(nx, ny, grid) and (nx, ny) not in visited:
                visited.add((nx, ny))
                queue.append((nx, ny))
                path[(nx, ny)] = (x, y)

    # Reconstruct the path
    if end in path:
        path_list = []
        while end:
            path_list.append(end)
            end = path[end]
        return list(reversed(path_list))
    else:
        return None

# Example usage
